-- --- product structure -------------------------------------------------------------------------
ALTER TABLE product_categories
  ADD CONSTRAINT ck_product_categories__code CHECK (code ~ '^[a-z][a-z0-9_]*$'),
  ADD CONSTRAINT ck_product_categories__not_own_parent CHECK (parent_id IS NULL OR parent_id <> id);

-- D-100: a type is quoted instantly only through a calculator.
ALTER TABLE product_types
  ADD CONSTRAINT ck_product_types__code CHECK (code ~ '^[a-z][a-z0-9_]*$'),
  ADD CONSTRAINT ck_product_types__instant_needs_calculator CHECK (quote_mode <> 'instant' OR calculator_key IS NOT NULL);

ALTER TABLE print_types
  ADD CONSTRAINT ck_print_types__code CHECK (code ~ '^[a-z][a-z0-9_]*$');

ALTER TABLE catalog_products
  ADD CONSTRAINT ck_catalog_products__slug CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');

ALTER TABLE standard_sizes
  ADD CONSTRAINT ck_standard_sizes__dimensions CHECK (length_mm > 0 AND width_mm > 0 AND height_mm >= 0),
  ADD CONSTRAINT ck_standard_sizes__calc_dimensions CHECK (
    (calc_length_mm IS NULL OR calc_length_mm > 0) AND (calc_width_mm IS NULL OR calc_width_mm > 0)
    AND (calc_height_mm IS NULL OR calc_height_mm >= 0));

ALTER TABLE sub_patterns
  ADD CONSTRAINT ck_sub_patterns__seq CHECK (seq > 0);

ALTER TABLE patterns
  ADD CONSTRAINT ck_patterns__constraints_object CHECK (jsonb_typeof(constraints) = 'object');

-- --- materials & processes ---------------------------------------------------------------------
ALTER TABLE flute_types
  ADD CONSTRAINT ck_flute_types__layers CHECK (layers > 0);

ALTER TABLE materials
  ADD CONSTRAINT ck_materials__gsm CHECK (gsm IS NULL OR gsm > 0),
  ADD CONSTRAINT ck_materials__micron CHECK (micron IS NULL OR micron > 0);

-- `option_id` / `item_id` point at the definition table named by the option kind. Kinds without a
-- definition table yet (print_side, process) are refused until a deliverable defines them.
CREATE FUNCTION catalog_option_exists(kind catalog_option_kind, option_id bigint) RETURNS boolean
  LANGUAGE plpgsql STABLE AS $$
BEGIN
  RETURN CASE kind
    WHEN 'material'   THEN EXISTS (SELECT 1 FROM materials    WHERE id = option_id)
    WHEN 'finish'     THEN EXISTS (SELECT 1 FROM finishes     WHERE id = option_id)
    WHEN 'coating'    THEN EXISTS (SELECT 1 FROM finishes     WHERE id = option_id AND finish_kind IN ('coating', 'lamination'))
    WHEN 'ink_colour' THEN EXISTS (SELECT 1 FROM ink_colours  WHERE id = option_id)
    WHEN 'diecut'     THEN EXISTS (SELECT 1 FROM diecut_types WHERE id = option_id)
    WHEN 'assembly'   THEN EXISTS (SELECT 1 FROM assemblies   WHERE id = option_id)
    WHEN 'print_type' THEN EXISTS (SELECT 1 FROM print_types  WHERE id = option_id)
    WHEN 'pattern'    THEN EXISTS (SELECT 1 FROM patterns     WHERE id = option_id)
    ELSE false
  END;
END
$$;

CREATE FUNCTION check_catalog_product_option() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT catalog_option_exists(NEW.option_kind, NEW.option_id) THEN
    RAISE EXCEPTION 'catalog_product_options: % % does not exist', NEW.option_kind, NEW.option_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_catalog_product_options__option_fk BEFORE INSERT OR UPDATE ON catalog_product_options
  FOR EACH ROW EXECUTE FUNCTION check_catalog_product_option();

