    (capacity_ml IS NULL OR capacity_ml >= 0) AND (length_mm IS NULL OR length_mm > 0)
    AND (width_mm IS NULL OR width_mm > 0) AND (height_mm IS NULL OR height_mm >= 0)
    AND (weight_g IS NULL OR weight_g >= 0));

