CREATE FUNCTION check_video_subject() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  found boolean;
BEGIN
  found := CASE NEW.subject_type
    WHEN 'catalog_product'  THEN EXISTS (SELECT 1 FROM catalog_products  WHERE id = NEW.subject_id)
    WHEN 'showcase_product' THEN EXISTS (SELECT 1 FROM showcase_products WHERE id = NEW.subject_id)
    WHEN 'stock_product'    THEN EXISTS (SELECT 1 FROM stock_products    WHERE id = NEW.subject_id)
    WHEN 'article'          THEN EXISTS (SELECT 1 FROM articles          WHERE id = NEW.subject_id)
    ELSE false
  END;
  IF NOT found THEN
    RAISE EXCEPTION 'videos: % % does not exist', NEW.subject_type, NEW.subject_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_videos__subject_fk BEFORE INSERT OR UPDATE ON videos
  FOR EACH ROW EXECUTE FUNCTION check_video_subject();

